command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin main work/shell-provider-copyout-20261007 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne "700500d92442f25002fb707031d7c2ff2cb2052f"){throw "main moved"}
if((& git rev-parse refs/remotes/origin/work/shell-provider-copyout-20261007).Trim() -ne "32648cfeb5e92594619b9ed24b2568b18d71a2e8"){throw "candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "persistent checkout dirty"}
& git diff --quiet de413f5302afd92af7b192dec586db22fff2dff3 32648cfeb5e92594619b9ed24b2568b18d71a2e8 -- app/winui src/base
if($LASTEXITCODE -ne 0){throw "product source changed after accepted Release build"}
$exe=Join-Path $repo "out\winui\Release\flyExplorer.exe"
if(-not(Test-Path -LiteralPath $exe -PathType Leaf)){throw "accepted Release runtime missing"}
& git switch --detach 32648cfeb5e92594619b9ed24b2568b18d71a2e8
if($LASTEXITCODE -ne 0){throw "checkout failed"}
& python -X utf8 tests\winui\test_shell_provider_copyout_gui.py --configuration Release
if($LASTEXITCODE -ne 0){throw "provider copyout GUI failed"}
& git switch main
if($LASTEXITCODE -ne 0){throw "restore main failed"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "restore main ff failed"}
Write-Host "SHELL_PROVIDER_COPYOUT_VALIDATION=PASS"
